<div data-livewire-summary="true" class="grid divide-y divide-[var(--ui-line)] sm:grid-cols-2 sm:divide-x sm:divide-y-0 xl:grid-cols-4">
    <x-stat-item label="Database aktif" :value="$schoolName" :hint="'NPSN '.$npsn.' · Session '.$sessionId" :value-class="$schoolName !== 'Belum dipilih' ? 'text-[var(--ui-fg-strong)]' : 'text-rose-700'" icon="database" :icon-class="$schoolName !== 'Belum dipilih' ? 'text-[var(--ui-fg-strong)]' : 'text-rose-700'" />
    <x-stat-item label="Kesehatan" :value="$health" :hint="$healthHint" :value-class="$healthHint === 'Tidak ada masalah terdeteksi' ? 'text-emerald-700' : 'text-amber-700'" :icon-class="$healthHint === 'Tidak ada masalah terdeteksi' ? 'text-emerald-700' : 'text-amber-700'" icon="check" />
    <x-stat-item label="Penyimpanan aktif" :value="$storage" :hint="'DB '.$databaseSize.' · WAL '.$walSize" value-class="text-[var(--theme-content-accent)]" icon="archive" icon-class="text-[var(--theme-content-accent)]" />
    <x-stat-item label="Struktur aktif" :value="number_format($tableCount, 0, ',', '.').' tabel'" :hint="$tableRows.' baris terhitung'" value-class="text-[var(--ui-fg-strong)]" icon="server" icon-class="text-[var(--ui-fg-strong)]" />
</div>
